/**
 * Body of `PATCH /api/entities/{id}`. `reembed_job_id` is present only
 * when the description changed and a re-embed job was queued.
 */
export interface EntityUpdateResponse {
  aliases: string[]
  canonical_name: string
  created_at: string
  description: string
  entity_type: EntityType
  first_seen: string
  id: number
  is_quarantined: boolean
  quarantine_reason: string
  quarantined_at: string
  reembed_job_id?: string
  updated_at: string
}

/**
 * Body of a non-2xx JSON response from the REST API.
 *
 * Exported for the webapp, never validated: the runtime check covers 2xx
 * bodies only. A few routes add keys, e.g. the 409 from
 * `POST /api/entities/{id}/aliases` names the entity that owns the alias.
 */
export interface ErrorResponse {
  error: string
  message?: string
}
